create table public.companies(id uuid primary key default gen_random_uuid(),name text not null,code text not null unique,slug text not null unique check(slug ~ '^[a-z0-9-]+$'),timezone text not null default 'America/Monterrey',status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,company_id uuid not null references public.companies(id) on delete restrict,role text not null check(role in('platform_owner','company_admin','manager','supervisor','operator','viewer')),display_name text,status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.clients(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,code text,status text not null default 'active',created_at timestamptz default now(),updated_at timestamptz default now(),unique(company_id,name));
create table public.part_numbers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,client_id uuid references public.clients(id) on delete set null,part_number text not null,description text,unit_of_measure text not null default 'pcs',status text not null default 'active',created_at timestamptz default now(),updated_at timestamptz default now(),unique(company_id,part_number));
create table public.operations(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,code text,sequence integer,status text not null default 'active',created_at timestamptz default now(),updated_at timestamptz default now(),unique(company_id,name));
create table public.machines(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,code text not null,status text not null default 'active',created_at timestamptz default now(),updated_at timestamptz default now(),unique(company_id,code));
create table public.part_operations(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,part_number_id uuid not null references public.part_numbers(id),operation_id uuid not null references public.operations(id),sequence integer not null,is_finish_good boolean not null default false,status text not null default 'active',created_at timestamptz default now(),updated_at timestamptz default now(),unique(part_number_id,operation_id));
create table public.part_operation_machines(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,part_operation_id uuid not null references public.part_operations(id) on delete cascade,machine_id uuid not null references public.machines(id),ideal_cycle_time_seconds numeric(12,3),status text not null default 'active',unique(part_operation_id,machine_id));
create table public.personnel(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,employee_number text,type text not null default 'operator' check(type in('operator','supervisor','both')),status text not null default 'active',unique(company_id,employee_number));
create table public.shifts(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,code text,start_time time,end_time time,status text not null default 'active',unique(company_id,name));
create table public.defect_catalog(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,code text not null,name text not null,description text,category text,status text not null default 'active',unique(company_id,code));
create table public.downtime_reasons(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,code text not null,name text not null,category text,planned boolean not null default false,status text not null default 'active',unique(company_id,code));
create table public.production_runs(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,part_number_id uuid not null references public.part_numbers(id),lot_number text not null,start_date date,end_date date,status text not null default 'open',created_at timestamptz default now(),updated_at timestamptz default now(),unique(company_id,part_number_id,lot_number));
create table public.production_records(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,production_run_id uuid references public.production_runs(id) on delete set null,production_date date not null default current_date,part_number_id uuid not null references public.part_numbers(id),part_operation_id uuid references public.part_operations(id),machine_id uuid references public.machines(id),lot_number text,shift_id uuid references public.shifts(id),operator_id uuid references public.personnel(id),supervisor_id uuid references public.personnel(id),quantity numeric(14,3) not null check(quantity>=0),created_by uuid references auth.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.quality_records(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,production_record_id uuid references public.production_records(id) on delete set null,part_number_id uuid not null references public.part_numbers(id),part_operation_id uuid references public.part_operations(id),machine_id uuid references public.machines(id),lot_number text,shift_id uuid references public.shifts(id),defect_id uuid not null references public.defect_catalog(id),quantity numeric(14,3) not null check(quantity>=0),comments text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table public.downtime_records(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,downtime_date date not null default current_date,machine_id uuid not null references public.machines(id),part_number_id uuid references public.part_numbers(id),part_operation_id uuid references public.part_operations(id),shift_id uuid references public.shifts(id),reason_id uuid not null references public.downtime_reasons(id),duration_minutes numeric(14,3) not null check(duration_minutes>=0),comments text,created_by uuid references auth.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.company_settings(company_id uuid primary key references public.companies(id) on delete cascade,default_timezone text not null default 'America/Monterrey',default_language text not null default 'en',default_theme text not null default 'light',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.user_preferences(user_id uuid primary key references auth.users(id) on delete cascade,language text not null default 'en',theme text not null default 'light',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.dashboard_metric_settings(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,metric_key text not null,minimum numeric,target numeric,maximum numeric,unique(company_id,metric_key));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),company_id uuid references public.companies(id),user_id uuid references auth.users(id),action text not null,entity_type text,entity_id uuid,before_data jsonb,after_data jsonb,created_at timestamptz default now());
